export enum SupportedDatastores {
    s3 = 's3',
}

/**
 * The region used for datastore based measurements when the caller does not provide one.
 */
export const DEFAULT_DATASTORE_REGION = 'us-east-1';

/**
 * The prefix of every IAM role provisioned for a datastore based measurement.
 */
export const DATASTORE_ROLE_PREFIX = 'datastore';

/**
 *
 * This Class represents the access information and control data structure for Datastore based Measurement solutions
 * Specifically this is the access information needed for connectors inside of Confluent Cloud to pull data from a clients env.
 * There are many different connectors with different access and control needs.
 * For example a MySQL connector is not the same as a Kinesis Connector
 * */
export class DatastoreAccessInformation {
    /**
     * The datastore platform enterprise ingests usage records from. Optional, default is `s3`.
     *
     */
    @Matches(
        `^${Object.values(SupportedDatastores)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsOptional()
    @ApiProperty({
        enum: SupportedDatastores,
        isArray: false,
        required: false,
        examples: ['s3'],
    })
    public platform?: SupportedDatastores;

    /**
     * The unique ID of the cloud account owned by the SaaS business which writes the usage records. Required.
     * @example "623673123435"
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({ example: '623673123435' })
    public accountId: string;

    /**
     * The region of the datastore enterprise ingests usage records from. Optional, default is `us-east-1`.
     * @example "us-east-1"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, example: DEFAULT_DATASTORE_REGION })
    public region?: string;

    /**
     * The IAM role generated by enterprise. It is assumable by the `accountId` provided,
     * and grants access to the ingestion and dead letter queue locations of this business.
     * <br><br>
     * Read only, generated by enterprise.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ readOnly: true })
    public iamRoleArn?: string;

    /**
     * The external ID which must be used when assuming the generated `iamRoleArn`.
     * <br><br>
     * Read only, generated by enterprise.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ readOnly: true })
    public externalId?: string;

    /**
     * The location usage records must be written to.
     * <br><br>
     * Read only, generated by enterprise.
     * @example "s3://enterprise-usage-record-dump-bucket/My Cool Corp"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ readOnly: true })
    public ingestion?: string;

    /**
     * The location where usage records that failed processing are written to.
     * <br><br>
     * Read only, generated by enterprise.
     * @example "s3://enterprise-usage-record-dlq-bucket/My Cool Corp"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ readOnly: true })
    public dlq?: string;

    @ApiHideProperty()
    @IsOptional()
    public businessID?: string;

    @ApiHideProperty()
    @IsOptional()
    public measurementId?: string;

    constructor(datastoreAccessInformation: DatastoreAccessInformation) {
        if (datastoreAccessInformation) {
            const {
                platform,
                accountId,
                region,
                iamRoleArn,
                externalId,
                ingestion,
                dlq,
                businessID,
                measurementId,
            } = datastoreAccessInformation;
            this.platform = platform
                ? (platform.toLowerCase() as SupportedDatastores)
                : (SupportedDatastores.s3 as SupportedDatastores);
            this.accountId = accountId;
            this.region = region ? region : DEFAULT_DATASTORE_REGION;
            this.iamRoleArn = iamRoleArn;
            this.externalId = externalId;
            this.ingestion = ingestion;
            this.dlq = dlq;
            this.businessID = businessID;
            this.measurementId = measurementId;
        }
    }

    public static transformer(datastoreAccessInformation: DatastoreAccessInformation, influxPoint: Point) {
        if (datastoreAccessInformation) {
            const { platform, accountId, region, iamRoleArn, externalId, ingestion, dlq } =
                datastoreAccessInformation;
            if (platform) influxPoint.tag('platform', platform);
            if (accountId) influxPoint.tag('accountId', accountId);
            if (region) influxPoint.tag('region', region);
            if (iamRoleArn) influxPoint.tag('iamRoleArn', iamRoleArn);
            if (externalId) influxPoint.tag('externalId', externalId);
            if (ingestion) influxPoint.tag('ingestion', ingestion);
            if (dlq) influxPoint.tag('dlq', dlq);
        }
        return influxPoint;
    }

    public static dbModelToEntity({
        platform,
        accountId,
        region,
        iamRoleArn,
        externalId,
        ingestion,
        dlq,
        businessID,
        measurementId,
    }: {
        [x: string]: any;
    }) {
        return new DatastoreAccessInformation({
            platform,
            accountId,
            region,
            iamRoleArn,
            externalId,
            ingestion,
            dlq,
            businessID,
            measurementId,
        });
    }

    /**
     * The unique name of the IAM role and the IAM policy provisioned for a datastore based measurement.
     */
    public static roleName({ businessID, measurementId }: { businessID?: string; measurementId?: string }) {
        return `${DATASTORE_ROLE_PREFIX}-${businessID}-${measurementId}`;
    }

    /**
     * The prefix inside of the ingestion and dead letter queue buckets reserved for a business.
     */
    public static prefix(businessID: string) {
        return `${businessID}/`;
    }

    /**
     * The location, in S3 URI form, a business reads or writes usage records from.
     */
    public static location(bucket: string, businessID: string) {
        return `s3://${bucket}/${businessID}`;
    }

    /**
     * The policy allowing the SaaS business account to assume the generated role with the generated external ID.
     */
    public static trustPolicy({ accountId, externalId }: { accountId: string; externalId: string }) {
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Sid: 'AllowDatastoreAccountToAssumeRole',
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${accountId}:root`,
                    },
                    Action: 'sts:AssumeRole',
                    Condition: {
                        StringEquals: {
                            'sts:ExternalId': externalId,
                        },
                    },
                },
            ],
        };
    }

    /**
     * The policy scoping the generated role down to the ingestion and dead letter queue prefixes of a business.
     */
    public static accessPolicy({
        businessID,
        ingestionBucket,
        dlqBucket,
    }: {
        businessID: string;
        ingestionBucket: string;
        dlqBucket: string;
    }) {
        const prefix = DatastoreAccessInformation.prefix(businessID);
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Sid: 'IngestionAccess',
                    Effect: 'Allow',
                    Action: ['s3:PutObject', 's3:GetObject', 's3:AbortMultipartUpload'],
                    Resource: [`arn:aws:s3:::${ingestionBucket}/${prefix}*`],
                },
                {
                    Sid: 'DeadLetterQueueAccess',
                    Effect: 'Allow',
                    Action: ['s3:GetObject'],
                    Resource: [`arn:aws:s3:::${dlqBucket}/${prefix}*`],
                },
                {
                    Sid: 'ListPrefixes',
                    Effect: 'Allow',
                    Action: ['s3:ListBucket'],
                    Resource: [`arn:aws:s3:::${ingestionBucket}`, `arn:aws:s3:::${dlqBucket}`],
                    Condition: {
                        StringLike: {
                            's3:prefix': [`${prefix}*`],
                        },
                    },
                },
            ],
        };
    }

    /**
     * Provisions the access needed by a SaaS business to deliver usage records into enterprise.
     * A dedicated IAM role, and an equally named policy, are created per measurement.
     * The role is only assumable by the account of the business, and only with the freshly generated external ID.
     */
    public static async setupAccess(
        dbAccessInformation: DatastoreAccessInformation,
        context: { businessID?: string; measurementId?: string } = {}
    ): Promise<DatastoreAccessInformation> {
        const platform = dbAccessInformation?.platform
            ? (dbAccessInformation.platform.toLowerCase() as SupportedDatastores)
            : SupportedDatastores.s3;

        if (platform !== SupportedDatastores.s3) {
            return dbAccessInformation;
        }

        const businessID = context.businessID ? context.businessID : dbAccessInformation.businessID;
        const measurementId = context.measurementId ? context.measurementId : dbAccessInformation.measurementId;
        const { accountId } = dbAccessInformation;
        const ingestionBucket = `${process.env.DB_MEASUREMENT_BUCKET_NAME}`;
        const dlqBucket = `${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}`;
        const region = dbAccessInformation.region ? dbAccessInformation.region : DEFAULT_DATASTORE_REGION;
        const roleName = DatastoreAccessInformation.roleName({ businessID, measurementId });
        // A fresh external ID per measurement so a leaked ID can never be replayed on another measurement
        const externalId = dbAccessInformation.externalId ? dbAccessInformation.externalId : randomUUID();

        try {
            const iam = new IAM({ region: process.env.AWS_REGION ? process.env.AWS_REGION : region });
            const { Role } = await iam.createRole({
                RoleName: roleName,
                AssumeRolePolicyDocument: JSON.stringify(
                    DatastoreAccessInformation.trustPolicy({ accountId, externalId })
                ),
            });
            await iam.putRolePolicy({
                RoleName: roleName,
                PolicyName: roleName,
                PolicyDocument: JSON.stringify(
                    DatastoreAccessInformation.accessPolicy({ businessID, ingestionBucket, dlqBucket })
                ),
            });

            dbAccessInformation.platform = platform;
            dbAccessInformation.region = region;
            dbAccessInformation.externalId = externalId;
            dbAccessInformation.iamRoleArn = Role?.Arn
                ? Role.Arn
                : `arn:aws:iam::${process.env.AWS_ACCOUNT_ID}:role/${roleName}`;
            dbAccessInformation.ingestion = DatastoreAccessInformation.location(ingestionBucket, businessID);
            dbAccessInformation.dlq = DatastoreAccessInformation.location(dlqBucket, businessID);

            return dbAccessInformation;
        } catch (e) {
            if (DatastoreAccessInformation.isInvalidAccountError(e)) {
                throw new BadRequestException(`accountId: ${accountId} is invalid`);
            }
            throw e;
        }
    }

    /**
     * Points the trust of an already provisioned role at the, potentially updated, account of the business.
     * The role itself, and its external ID, are preserved so previously shared credentials keep working.
     */
    public static async updateAccess(
        dbAccessInformation: DatastoreAccessInformation,
        context: { businessID?: string; measurementId?: string } = {}
    ): Promise<DatastoreAccessInformation> {
        const platform = dbAccessInformation?.platform
            ? (dbAccessInformation.platform.toLowerCase() as SupportedDatastores)
            : SupportedDatastores.s3;

        if (platform !== SupportedDatastores.s3) {
            return dbAccessInformation;
        }

        const businessID = context.businessID ? context.businessID : dbAccessInformation.businessID;
        const measurementId = context.measurementId ? context.measurementId : dbAccessInformation.measurementId;
        const { accountId, externalId, iamRoleArn } = dbAccessInformation;

        if (!accountId || !externalId) {
            // Nothing was provisioned for this measurement, there is no trust to update
            return dbAccessInformation;
        }

        const roleName = DatastoreAccessInformation.roleNameFromArn(iamRoleArn)
            ? DatastoreAccessInformation.roleNameFromArn(iamRoleArn)
            : DatastoreAccessInformation.roleName({ businessID, measurementId });

        try {
            const region = dbAccessInformation.region ? dbAccessInformation.region : DEFAULT_DATASTORE_REGION;
            const iam = new IAM({ region: process.env.AWS_REGION ? process.env.AWS_REGION : region });
            await iam.updateAssumeRolePolicy({
                RoleName: roleName,
                PolicyDocument: JSON.stringify(DatastoreAccessInformation.trustPolicy({ accountId, externalId })),
            });

            return dbAccessInformation;
        } catch (e) {
            if (DatastoreAccessInformation.isInvalidAccountError(e)) {
                throw new BadRequestException(`accountId: ${accountId} is invalid`);
            }
            throw e;
        }
    }

    private static roleNameFromArn(iamRoleArn?: string) {
        if (!iamRoleArn) {
            return undefined;
        }
        const [, roleName] = iamRoleArn.split(':role/');
        return roleName;
    }

    private static isInvalidAccountError(e) {
        const code = e?.Code ? e.Code : e?.name;
        return code === 'MalformedPolicyDocument' || code === 'MalformedPolicy' || code === 'InvalidInput';
    }
}

