    /**
     * Hands a measurement which could not be processed over to the dead letter queue.
     * The failed input, together with the metadata of the processing attempt, is written under the
     * key of the source object mirrored inside of the dead letter queue, suffixed with `.message.text`.
     */
    static async publishFailureToDLQ(publishFailureRequest: PublishFailureToDLQRequest) {
        const { input, message, sourceKey, s3Key, bucket, businessID, error, metadata } = publishFailureRequest
            ? publishFailureRequest
            : {};

        const failedInput = input === undefined ? message : input;
        const source = sourceKey ? sourceKey : s3Key;
        const dlqBucket = bucket ? bucket : `${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}`;
        const key = `${StandardMeasurementEntity.toRelativeKey(source)}${DLQ_KEY_SUFFIX}`;

        const body = {
            message: failedInput,
            s3Key: source,
            businessID,
            error: StandardMeasurementEntity.describeError(error),
            failedAt: new Date().toISOString(),
            ...metadata,
        };

        try {
            const s3 = new S3({ region: process.env.AWS_REGION });
            await s3.putObject({
                Bucket: dlqBucket,
                Key: key,
                Body: JSON.stringify(body),
            });
        } catch (err) {
            AuditService.publishEvent({
                data: [{ err }],
                message: 'Failed to publish Measurement to the DLQ',
                topic: AuditScope.ERROR,
            });
            throw err;
        }

        return { message: 'Published failure to DLQ', bucket: dlqBucket, key };
    }

    /**
     * The key of an object relative to its bucket. Keys which are relative already are left untouched.
     */
    private static toRelativeKey(sourceKey?: string) {
        if (!sourceKey) {
            return `unknown/${randomUUID()}`;
        }
        return sourceKey.replace(/^s3:\/\/[^/]+\/?/, '').replace(/^\/+/, '');
    }

    private static describeError(error?: unknown) {
        if (!error) {
            return undefined;
        }
        if (error instanceof Error) {
            return { name: error.name, message: error.message };
        }
        return error;
    }
}

