import { Body, Controller, Logger, Post, Req, UseGuards } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { ApiBadRequestResponse, ApiCreatedResponse, ApiOperation, ApiTags } from '@nestjs/swagger';
import { BasicResponseDTO } from '../basicResponseDTO';
import { CreateUsageDto } from './dto/create-usage.dto';
import { UsageService } from './usage.service';
import { Request } from 'express';
import { DbMeasuredusageDto } from './dto/dbmeasuredUsage.dto';
import { LogGaurd } from '../authz/logGaurd';
import { StandardMeasurementEntity } from '../measurement-config/entities/standardMeasurement.entity';

@ApiTags('Usage')
@Controller('usage')
export class UsageController {
    private static readonly logger = new Logger(UsageController.name);
    constructor(private readonly usageService: UsageService) {}

    /**
     * Collect usage data by API-based method.
     * See <a href="https://docs.enterprise.tech/measure-usage-and-collect-data/measure-and-collect-usage-data-at-production-scale">Measure and Collect Usage Data At Production Scale</a>
     * for full documentation on Enterprise <b>Usage Measurement and Collection</b>.
     * @param createUsageDto
     * @param request
     */
    @ApiCreatedResponse({
        status: 201,
        description: 'OK',
        type: BasicResponseDTO,
    })
    @ApiBadRequestResponse({
        status: 400,
        description: 'Bad Request',
        type: BasicResponseDTO,
    })
    @ApiOperation({ operationId: 'Collect usage data' })
    @UseGuards(AuthGuard('jwt'))
    @Post()
    create(@Body() createUsageDto: CreateUsageDto, @Req() request: Request) {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        const { businessID } = request.user;
        return this.usageService.create({ ...createUsageDto, businessID });
    }

    /**
     * Collect usage data by datastore-based method.
     * The internal connector delivers one usage record, together with the key of the object it was read from.
     * The first segment of that key is the businessID the record belongs to.
     * Records which cannot be processed are handed over to the dead letter queue instead of being dropped.
     * @param createUsageDto
     */
    @UseGuards(LogGaurd, AuthGuard('jwt'))
    @Post('db')
    async dbUsage(@Body() createUsageDto: DbMeasuredusageDto): Promise<BasicResponseDTO> {
        UsageController.logger.log('Starting DB Usage Endpoint execution');

        const { message, s3Key } = createUsageDto ? createUsageDto : ({} as DbMeasuredusageDto);

        // TODO: check if the passed in BusinessID is an authorized producer, if not throw message away
        try {
            const businessID = UsageController.businessIDFromKey(s3Key);
            const record = UsageController.parseRecord(message);
            return await this.usageService.create({ ...record, businessID });
        } catch (error) {
            UsageController.logger.error('Failed to process DB measured usage record', error);
            await StandardMeasurementEntity.publishFailureToDLQ({
                input: message,
                sourceKey: s3Key,
                businessID: s3Key ? UsageController.firstSegment(s3Key) : undefined,
                error,
                metadata: { processor: UsageController.name, endpoint: 'usage/db' },
            });
            return { message: 'Failed to process usage record, published to DLQ' };
        }
    }

    /**
     * The businessID owning a record is the first segment of the key of the object holding it.
     */
    private static businessIDFromKey(s3Key?: string) {
        const businessID = s3Key ? UsageController.firstSegment(s3Key) : undefined;
        if (!businessID) {
            throw new Error('No s3Key provided, the businessID of the usage record cannot be determined');
        }
        return businessID;
    }

    private static firstSegment(s3Key: string) {
        const [businessID] = s3Key.replace(/^s3:\/\/[^/]+\/?/, '').replace(/^\/+/, '').split('/');
        return businessID;
    }

    private static parseRecord(message: unknown) {
        const record = typeof message === 'string' ? JSON.parse(message) : message;
        if (!record || typeof record !== 'object' || Array.isArray(record)) {
            throw new Error('The usage record delivered is not a single usage record');
        }
        return record;
    }
}

/**
 * The private API exposes the same usage endpoints, the datastore based connector delivers records through it.
 */
@ApiTags('Usage')
@Controller('usage')
export class PrivateAPIUsageController extends UsageController {}

