import {
    CreateRoleCommand,
    IAMClient,
    PutRolePolicyCommand,
    UpdateAssumeRolePolicyCommand,
} from '@aws-sdk/client-iam';
import { mockClient } from 'aws-sdk-client-mock';
import { DatastoreAccessInformation, SupportedDatastores } from './measurement-config.entity';

const iamMock = mockClient(IAMClient);

describe('DatastoreAccessInformation', () => {
    const businessID = 'fakeBusiness';
    const measurementId = 'fakeMeasurement';
    const accountId = '623673123435';

    beforeEach(() => {
        iamMock.reset();
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'enterprise-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'enterprise-usage-record-dlq-bucket';
        process.env.AWS_REGION = 'us-east-1';
    });

    it('defaults the platform and the region', () => {
        const accessInformation = new DatastoreAccessInformation({ accountId } as DatastoreAccessInformation);

        expect(accessInformation.platform).toEqual(SupportedDatastores.s3);
        expect(accessInformation.region).toEqual('us-east-1');
    });

    it('provisions a role trusting the account of the business with a fresh external id', async () => {
        iamMock.on(CreateRoleCommand).resolves({
            Role: { Arn: `arn:aws:iam::647662420899:role/datastore-${businessID}-${measurementId}` },
        } as never);

        const accessInformation = await DatastoreAccessInformation.setupAccess(
            new DatastoreAccessInformation({ accountId, businessID, measurementId } as DatastoreAccessInformation)
        );

        const [createRole] = iamMock.commandCalls(CreateRoleCommand);
        expect(createRole.args[0].input.RoleName).toEqual(`datastore-${businessID}-${measurementId}`);

        const trustPolicy = JSON.parse(createRole.args[0].input.AssumeRolePolicyDocument);
        expect(trustPolicy.Statement[0].Principal.AWS).toEqual(`arn:aws:iam::${accountId}:root`);
        expect(trustPolicy.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual(
            accessInformation.externalId
        );
        expect(accessInformation.externalId).toBeTruthy();
        expect(accessInformation.iamRoleArn).toEqual(
            `arn:aws:iam::647662420899:role/datastore-${businessID}-${measurementId}`
        );
        expect(accessInformation.ingestion).toContain(`enterprise-usage-record-dump-bucket/${businessID}`);
        expect(accessInformation.dlq).toContain(`enterprise-usage-record-dlq-bucket/${businessID}`);
    });

    it('scopes the policy of the role to the ingestion and dlq prefixes of the business', async () => {
        await DatastoreAccessInformation.setupAccess(
            new DatastoreAccessInformation({ accountId, businessID, measurementId } as DatastoreAccessInformation)
        );

        const [putRolePolicy] = iamMock.commandCalls(PutRolePolicyCommand);
        expect(putRolePolicy.args[0].input.RoleName).toEqual(`datastore-${businessID}-${measurementId}`);
        expect(putRolePolicy.args[0].input.PolicyDocument).toContain(
            `arn:aws:s3:::enterprise-usage-record-dump-bucket/${businessID}/*`
        );
        expect(putRolePolicy.args[0].input.PolicyDocument).toContain(
            `arn:aws:s3:::enterprise-usage-record-dlq-bucket/${businessID}/*`
        );
    });

    it('updates the trust of the role while preserving the role and the external id', async () => {
        const stored = new DatastoreAccessInformation({
            accountId,
            businessID,
            measurementId,
            externalId: 'storedExternalId',
            iamRoleArn: `arn:aws:iam::647662420899:role/datastore-${businessID}-${measurementId}`,
        } as DatastoreAccessInformation);

        const updated = await DatastoreAccessInformation.updateAccess(
            new DatastoreAccessInformation({ ...stored, accountId: '999999999999' } as DatastoreAccessInformation)
        );

        const [updateTrust] = iamMock.commandCalls(UpdateAssumeRolePolicyCommand);
        expect(updateTrust.args[0].input.RoleName).toEqual(`datastore-${businessID}-${measurementId}`);

        const trustPolicy = JSON.parse(updateTrust.args[0].input.PolicyDocument);
        expect(trustPolicy.Statement[0].Principal.AWS).toEqual('arn:aws:iam::999999999999:root');
        expect(trustPolicy.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual('storedExternalId');
        expect(updated.externalId).toEqual('storedExternalId');
        expect(updated.iamRoleArn).toEqual(stored.iamRoleArn);
        expect(iamMock.commandCalls(CreateRoleCommand)).toHaveLength(0);
    });
});

