describe('PrivateAPIUsageController', () => {
    const s3Mock = mockClient(S3Client);
    const mockCreate = jest.fn();
    const businessID = 'fakeBusiness';
    const s3Key = `${businessID}/topics/usage/partition=0/record.json`;
    const record = {
        timeStamp: '2023-02-08T19:24:10Z',
        dimensionId: 'da9611bd-e0f3-4c0d-a754-fda5be730872',
        applicationId: 'e8366954-6f36-47e9-8431-ac95f88b5cc7',
        recordValue: '0.87',
    };
    let controller: PrivateAPIUsageController;

    beforeEach(async () => {
        s3Mock.reset();
        jest.clearAllMocks();
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'enterprise-usage-record-dlq-bucket';

        const module: TestingModule = await Test.createTestingModule({
            controllers: [PrivateAPIUsageController],
        })
            .useMocker((token) => {
                if (token === UsageService) {
                    return { create: mockCreate };
                }
            })
            .compile();

        controller = module.get<PrivateAPIUsageController>(PrivateAPIUsageController);
    });

    it('creates usage for the business the record was delivered for', async () => {
        await controller.dbUsage({ message: JSON.stringify(record), s3Key });

        expect(mockCreate).toHaveBeenCalledWith({ ...record, businessID });
        expect(s3Mock.commandCalls(PutObjectCommand)).toHaveLength(0);
    });

    it('publishes malformed records to the dlq of the business', async () => {
        await controller.dbUsage({ message: 'this is not a usage record', s3Key });

        expect(mockCreate).not.toHaveBeenCalled();

        const [putObject] = s3Mock.commandCalls(PutObjectCommand);
        expect(putObject.args[0].input.Bucket).toEqual('enterprise-usage-record-dlq-bucket');
        expect(putObject.args[0].input.Key).toEqual(`${s3Key}.message.text`);

        const published = JSON.parse(`${putObject.args[0].input.Body}`);
        expect(published.message).toEqual('this is not a usage record');
        expect(published.businessID).toEqual(businessID);
        expect(published.error).toBeTruthy();
    });

    it('mirrors the key of the source object, no matter if it is an s3 uri or relative', async () => {
        await controller.dbUsage({
            message: '{"broken',
            s3Key: `s3://enterprise-usage-record-dump-bucket/${s3Key}`,
        });

        const [putObject] = s3Mock.commandCalls(PutObjectCommand);
        expect(putObject.args[0].input.Key).toEqual(`${s3Key}.message.text`);
    });
});

